{"new_text":"import re

def wrap(text, width):
    if width < 1:
        raise ValueError("width must be at least 1")

    if not text or text.isspace():
        return ""

    lines = text.splitlines()
    paragraphs_raw = []
    current_paragraph_lines = []
    for line in lines:
        if line.strip() == "":
            if current_paragraph_lines:
                paragraphs_raw.append(current_paragraph_lines)
                current_paragraph_lines = []
        else:
            current_paragraph_lines.append(line)
    if current_paragraph_lines:
        paragraphs_raw.append(current_paragraph_lines)

    processed_paragraphs = []
    for p_lines in paragraphs_raw:
        p_text = " ".join(p_lines)
        p_text = re.sub(r'\s+', ' ', p_text).strip()
        if p_text:
            processed_paragraphs.append(p_text)

    if not processed_paragraphs:
        return ""

    wrapped_paragraphs = []
    for p_text in processed_paragraphs:
        wrapped_paragraphs.append(_wrap_text(p_text, width))

    return "\n\n".join(wrapped_paragraphs)

def _wrap_text(text, width):
    words = text.split()
    if not words:
        return ""

    lines = []
    current_line = []
    current_line_len = 0

    for word in words:
        if len(word) > width:
            if current_line:
                lines.append(" ".join(current_line))
                current_line = []
                current_line_len = 0

            for i in range(0, len(word), width):
                chunk = word[i:i+width]
                if i + width < len(word):
                    lines.append(chunk)
                else:
                    current_line.append(chunk)
                    current_line_len = len(chunk)
            continue

        space_needed = 1 if current_line else 0
        if current_line_len + space_needed + len(word) <= width:
            current_line.append(word)
            current_line_len += space_needed + len(word)
        else:
            if current_line:
                lines.append(" ".join(current_line))
            current_line = [word]
            current_line_len = len(word)

    if current_line:
        lines.append(" ".join(current_line))

    return "\n".join(lines)
